    StringBuilder token = new StringBuilder();
    int currentChar = 0;
    while (currentChar < input.length()) {
        char ch = input.charAt(currentChar);
        boolean isTerminator = false;
        for (char terminator : terminators) {
            if (ch == terminator) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;
        }
        token.append(ch);
        currentChar++;
    }
    return token.toString();
}

