    private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<E> graph) {
        List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
        for (E edge : graph.getEdges()) {
            List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();
            Set<Integer> vertices = graph.getVertices();
            for (Integer vertex : vertices) {
                if (graph.hasEdge(vertex, edge.getSource()) && graph.hasEdge(vertex, edge.getTarget())) {
                    localSeparatorList.add(new Pair<>(vertex, edge.getSource()));
                    localSeparatorList.add(new Pair<>(vertex, edge.getTarget()));
                }
            }
            globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
        }
        return globalSeparatorList;
    }
}

