public class GraphUtils {
    private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
        if (vertices.isEmpty()) {
            return true;
        }

        Iterator<V> iterator = vertices.iterator();
        V vertex = iterator.next();
        Set<V> remainingVertices = new HashSet<>(vertices);
        remainingVertices.remove(vertex);

        for (V v : remainingVertices) {
            if (!graph.containsEdge(vertex, v)) {
                return false;
            }
        }

        return isClique(graph, remainingVertices);
    }
}

